using System;using System.IO;using System.Drawing;using System.Drawing.Drawing2D;
class Contact {static void Main(string[]args){string root=args[0];string[] rows=File.ReadAllLines(Path.Combine(root,"contact-index.tsv"));for(int page=0;page*20<rows.Length;page++){using(Bitmap b=new Bitmap(1024,1300))using(Graphics g=Graphics.FromImage(b))using(Font font=new Font("Segoe UI",11)){g.Clear(Color.FromArgb(20,24,30));g.InterpolationMode=InterpolationMode.NearestNeighbor;g.PixelOffsetMode=PixelOffsetMode.Half;for(int i=0;i<20&&page*20+i<rows.Length;i++){string[] r=rows[page*20+i].Split('\t');int n=int.Parse(r[0]);int x=i%4*256,y=i/4*260;g.DrawString("G"+n.ToString("000")+" "+r[1],font,Brushes.White,x+4,y+2);string p=Path.Combine(root,"screens","G"+n.ToString("000")+"-input-1791.png");if(File.Exists(p)){using(Image img=Image.FromFile(p))g.DrawImage(img,x,y+20,256,240);}}b.Save(Path.Combine(root,"contact-"+(page+1)+".png"));}}}}
